param([string[]]$Locales=@('en','ru','es','zh','fr','de','mordor'))
$ErrorActionPreference='Stop';$taskRoot='D:\Codex\mdlxl-uv-grid-tutorial';$env:TEMP=$taskRoot+'\temp';$env:TMP=$env:TEMP;$env:MDLXL_TEMP=$env:TEMP
foreach($locale in $Locales){$capture=$taskRoot+'\work\captures\'+$locale;$raw=$capture+'\raw';if(Test-Path -LiteralPath $raw){if((Resolve-Path -LiteralPath $raw).Path -ne $raw){throw 'raw path'};Remove-Item -LiteralPath $raw -Recurse -Force};$env:MDLXL_HIDDEN_COMMAND='cmd /c "node '+$taskRoot+'\authoring\capture.cjs '+$locale+' > '+$taskRoot+'\work\capture-'+$locale+'.log 2>&1"';powershell -NoProfile -ExecutionPolicy Bypass -File ($taskRoot+'\mdlxl\scripts\hidden-run.ps1') -WorkDir ($taskRoot+'\mdlxl');if($LASTEXITCODE -ne 0){Get-Content ($taskRoot+'\work\capture-'+$locale+'.log') -Tail 20;exit 1};node ($taskRoot+'\authoring\encode.mjs') $locale;if($LASTEXITCODE -ne 0){exit 1};Write-Output ('FINISHED '+$locale)}
